window.VO = [{"start": 0.2, "dur": 2.664, "text": "Western Australia, 1932.", "b64": ""}, {"start": 2.9, "dur": 3.422, "text": "Twenty thousand emus were eating the farmers' wheat.", "b64": ""}, {"start": 7.7, "dur": 3.944, "text": "So the army sent two machine guns, and ten thousand bullets.", "b64": ""}, {"start": 11.7, "dur": 2.038, "text": "But the emus split up and ran.", "b64": ""}, {"start": 14.3, "dur": 3.056, "text": "Fifty kilometres an hour. No truck could keep up.", "b64": ""}, {"start": 17.55, "dur": 1.358, "text": "Then a gun jammed.", "b64": ""}, {"start": 19.85, "dur": 4.78, "text": "Nearly ten thousand bullets. Nine hundred and eighty-six emus.", "b64": ""}, {"start": 24.8, "dur": 1.437, "text": "Ten bullets per bird.", "b64": ""}, {"start": 27.4, "dur": 1.149, "text": "The army went home.", "b64": ""}, {"start": 29.6, "dur": 1.123, "text": "The emus won.", "b64": ""}];
